using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Text;
using System.Drawing;
using System.Diagnostics;
using System.Globalization;
using System.Security.Cryptography;
using System.Collections.Generic;
using System.Windows.Forms;

namespace AdhdWarrior {
 public class CalendarSyncSettings {public string Category {get;set;}public List<string> ImportedEventIds {get;set;}public string LastSync {get;set;}public CalendarSyncSettings(){Category="Work";ImportedEventIds=new List<string>();LastSync="";}}
 public class CalendarImportEvent {public string Id,Title,Due,DueTime;}
 public static class CalendarImport {
  static readonly byte[] Entropy=Encoding.UTF8.GetBytes("ADHD Warrior Google Calendar link");
  static string LinkPath {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AdhdWarrior","google-calendar-link.dat");}}
  public static bool Linked {get{return File.Exists(LinkPath);}}
  public static void SaveLink(string value){var uri=ValidateLink(value);Directory.CreateDirectory(Path.GetDirectoryName(LinkPath));File.WriteAllBytes(LinkPath,ProtectedData.Protect(Encoding.UTF8.GetBytes(uri.AbsoluteUri),Entropy,DataProtectionScope.CurrentUser));}
  public static string LoadLink(){if(!Linked)return "";return Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(LinkPath),Entropy,DataProtectionScope.CurrentUser));}
  public static void Disconnect(){if(Linked)File.Delete(LinkPath);}
  static Uri ValidateLink(string value){Uri uri;if(!Uri.TryCreate((value??"").Trim(),UriKind.Absolute,out uri)||uri.Scheme!="https"||(uri.Host!="calendar.google.com"&&uri.Host!="www.google.com")||!uri.AbsolutePath.ToLowerInvariant().Contains("/calendar/ical/"))throw new InvalidOperationException("Paste the Secret address in iCal format from Google Calendar settings.");return uri;}
  public static void Validate(CalendarSyncSettings settings){if(settings==null||settings.ImportedEventIds==null||settings.ImportedEventIds.Count>10000||settings.ImportedEventIds.Distinct().Count()!=settings.ImportedEventIds.Count||settings.ImportedEventIds.Any(x=>String.IsNullOrWhiteSpace(x)||x.Length>1000)||!new[]{"School","Work","Home","Life","Fun"}.Contains(settings.Category))throw new InvalidDataException("Invalid calendar settings.");DateTime parsed;if(settings.LastSync==null||settings.LastSync!=""&&!DateTime.TryParseExact(settings.LastSync,"yyyy-MM-dd HH:mm",CultureInfo.InvariantCulture,DateTimeStyles.None,out parsed))throw new InvalidDataException("Invalid calendar sync history.");}
  public static List<CalendarImportEvent> Parse(string text){var unfolded=(text??"").Replace("\r\n ","").Replace("\r\n\t","").Replace("\n ","").Replace("\n\t","");var result=new List<CalendarImportEvent>();foreach(var block in unfolded.Split(new[]{"BEGIN:VEVENT"},StringSplitOptions.None).Skip(1)){var end=block.IndexOf("END:VEVENT",StringComparison.Ordinal);if(end<0)continue;var lines=block.Substring(0,end).Replace("\r","").Split('\n');string uid=Value(lines,"UID"),title=Unescape(Value(lines,"SUMMARY")),start=Value(lines,"DTSTART");DateTime when;if(String.IsNullOrWhiteSpace(uid)||String.IsNullOrWhiteSpace(title)||!ParseDate(start,out when))continue;result.Add(new CalendarImportEvent {Id=uid,Title=title,Due=when.ToString("yyyy-MM-dd"),DueTime=start.Length>8?when.ToString("HH:mm"):""});}return result;}
  static string Value(string[] lines,string key){var line=lines.FirstOrDefault(x=>x.StartsWith(key+":",StringComparison.OrdinalIgnoreCase)||x.StartsWith(key+";",StringComparison.OrdinalIgnoreCase));if(line==null)return "";int colon=line.IndexOf(':');return colon<0?"":line.Substring(colon+1).Trim();}
  static string Unescape(string text){return text.Replace("\\n"," ").Replace("\\N"," ").Replace("\\,",",").Replace("\\;",";").Replace("\\\\","\\").Trim();}
  static bool ParseDate(string value,out DateTime result){result=DateTime.MinValue;if(String.IsNullOrEmpty(value))return false;string clean=value.EndsWith("Z")?value.Substring(0,value.Length-1):value;string[] formats={"yyyyMMdd","yyyyMMdd'T'HHmmss","yyyyMMdd'T'HHmm"};if(!DateTime.TryParseExact(clean,formats,CultureInfo.InvariantCulture,DateTimeStyles.None,out result))return false;if(value.EndsWith("Z"))result=DateTime.SpecifyKind(result,DateTimeKind.Utc).ToLocalTime();return true;}
  public static List<CalendarImportEvent> Download(){using(var client=new WebClient()){client.Headers[HttpRequestHeader.UserAgent]="ADHD Warrior Windows";return Parse(client.DownloadString(ValidateLink(LoadLink())));}}
 }
 public partial class MainWindow {
  void ShowCalendarSettings(){var settings=data.CalendarSync;Note("Google Calendar\nLink a Google calendar with its private iCal address. Sync is read-only: upcoming events become quests, existing quests are never deleted, and duplicate event IDs are skipped. The private address is encrypted for this Windows account and is not included in backups.");var panel=new FlowLayoutPanel {FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoSize=false,Height=245,Padding=new Padding(18),BackColor=Theme.Surface,Margin=new Padding(0,0,0,12)};Theme.Frame(panel,Theme.Gold);panel.Controls.Add(new Label {Text=CalendarImport.Linked?"Google Calendar linked · Last sync: "+(String.IsNullOrEmpty(settings.LastSync)?"Never":settings.LastSync):"Not linked",AutoSize=true,ForeColor=CalendarImport.Linked?Theme.Emerald:Theme.Muted});var link=new TextBox {Width=680,UseSystemPasswordChar=true};Theme.StyleInput(link);panel.Controls.Add(link);var row=new FlowLayoutPanel {AutoSize=true};row.Controls.Add(new Label {Text="Imported quest category",AutoSize=true,Padding=new Padding(0,7,6,0)});var category=new ComboBox {DropDownStyle=ComboBoxStyle.DropDownList,Width=130};category.Items.AddRange(new object[]{"School","Work","Home","Life","Fun"});category.SelectedItem=settings.Category;Theme.StyleInput(category);row.Controls.Add(category);panel.Controls.Add(row);var actions=new FlowLayoutPanel {AutoSize=true,WrapContents=false};actions.Controls.Add(Button(CalendarImport.Linked?"Save link and sync now":"Link and import now",()=>{try{if(!String.IsNullOrWhiteSpace(link.Text))CalendarImport.SaveLink(link.Text);if(!CalendarImport.Linked)throw new InvalidOperationException("Paste your Google Calendar secret iCal address first.");var events=CalendarImport.Download().Where(x=>String.CompareOrdinal(x.Due,DateTime.Today.AddDays(-1).ToString("yyyy-MM-dd"))>=0).Take(500).ToList();int added=0;if(Change(()=>{settings.Category=(string)category.SelectedItem;foreach(var item in events.Where(x=>!settings.ImportedEventIds.Contains(x.Id))){data.Quests.Add(new Quest {Title=item.Title,Category=settings.Category,Due=item.Due,DueTime=item.DueTime,CalendarEventId=item.Id});settings.ImportedEventIds.Add(item.Id);added++;}settings.LastSync=DateTime.Now.ToString("yyyy-MM-dd HH:mm");},"Google Calendar sync complete."))MessageBox.Show(this,added+" new calendar event"+(added==1?"":"s")+" imported as quests.","Google Calendar");}catch(Exception ex){MessageBox.Show(this,"Calendar sync failed. "+ex.Message,"Google Calendar",MessageBoxButtons.OK,MessageBoxIcon.Error);}}));actions.Controls.Add(Button("Open Google Calendar settings",()=>{try{Process.Start("https://calendar.google.com/calendar/u/0/r/settings");}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not open Google Calendar");}}));if(CalendarImport.Linked)actions.Controls.Add(Button("Disconnect",()=>{CalendarImport.Disconnect();status.Text="Google Calendar disconnected. Imported quests were kept.";Render();}));panel.Controls.Add(actions);cards.Controls.Add(panel);}
 }
}
